using System;
using System.Collections.Generic;
using Org.BouncyCastle.X509;

namespace ZonderqOS.SystemCore.Networking
{
    /// <summary>
    /// Embedded Root CA trust store for HTTPS OTA downloads (GitHub, GitHub CDN,
    /// Let's Encrypt, DigiCert, Sectigo, USERTrust, GlobalSign, Google Trust Services).
    /// </summary>
    public static class TlsTrustStore
    {
        private static readonly object CacheLock = new object();
        private static X509Certificate[] cachedRoots;

        private static readonly string[] EmbeddedRootDerBase64 =
        {
            // USERTrust ECC Certification Authority
            "",
            // USERTrust RSA Certification Authority
            "",
            // Sectigo Public Server Authentication Root E46
            "",
            // Sectigo Public Server Authentication Root R46
            "",
            // ISRG Root X1
            "",
            // ISRG Root X2
            "",
            // DigiCert Global Root G2
            "",
            // DigiCert Global Root G3
            "",
            // GlobalSign Root CA - R3
            "",
            // GTS Root R1
            "",
        };

        public static X509Certificate[] GetBuiltInRoots()
        {
            lock (CacheLock)
            {
                if (cachedRoots != null)
                    return cachedRoots;

                var parser = new X509CertificateParser();
                var list = new List<X509Certificate>(EmbeddedRootDerBase64.Length);
                for (int i = 0; i < EmbeddedRootDerBase64.Length; i++)
                {
                    try
                    {
                        byte[] der = Convert.FromBase64String(EmbeddedRootDerBase64[i]);
                        X509Certificate cert = parser.ReadCertificate(der);
                        if (cert != null)
                            list.Add(cert);
                    }
                    catch { }
                }
                cachedRoots = list.ToArray();
                return cachedRoots;
            }
        }

        /// <summary>
        /// Verifies an ordered TLS server certificate chain (leaf first) against
        /// the embedded root CAs (and optional explicit extra root for local test harnesses).
        /// </summary>
        public static bool VerifyChain(IList<X509Certificate> chain, string expectedHost, X509Certificate extraTrustedRoot, out string error)
        {
            error = string.Empty;
            if (chain == null || chain.Count == 0 || chain[0] == null)
            {
                error = "Server presented an empty certificate chain.";
                return false;
            }

            X509Certificate leaf = chain[0];
            if (!TlsHostnameMatcher.MatchesHostname(leaf, expectedHost))
            {
                error = "TLS certificate hostname mismatch for '" + expectedHost + "'.";
                return false;
            }

            // Enforce certificate validity window when system RTC looks plausible (>= 2025).
            DateTime nowUtc = DateTime.UtcNow;
            bool checkTime = nowUtc.Year >= 2025;
            if (checkTime)
            {
                for (int i = 0; i < chain.Count; i++)
                {
                    if (nowUtc < chain[i].NotBefore || nowUtc > chain[i].NotAfter)
                    {
                        error = "TLS certificate expired or not yet valid.";
                        return false;
                    }
                }
            }

            X509Certificate[] builtInRoots = GetBuiltInRoots();
            var roots = new List<X509Certificate>(builtInRoots.Length + 1);
            if (extraTrustedRoot != null)
                roots.Add(extraTrustedRoot);
            for (int i = 0; i < builtInRoots.Length; i++)
                roots.Add(builtInRoots[i]);

            // Walk from leaf up through intermediates until signed by a trusted root.
            X509Certificate current = leaf;
            var visited = new HashSet<int>();
            visited.Add(0);

            for (int depth = 0; depth < 10; depth++)
            {
                // 1. Check if current cert IS itself a trusted root or directly signed by one.
                for (int r = 0; r < roots.Count; r++)
                {
                    X509Certificate root = roots[r];
                    if (root == null)
                        continue;
                    if (ByteArrayEquals(current.GetEncoded(), root.GetEncoded()))
                        return true;
                    if (current.IssuerDN.Equivalent(root.SubjectDN, true))
                    {
                        try
                        {
                            current.Verify(root.GetPublicKey());
                            if (!checkTime || (nowUtc >= root.NotBefore && nowUtc <= root.NotAfter))
                                return true;
                        }
                        catch { }
                    }
                }

                // 2. Otherwise find the next CA intermediate in the server-supplied chain.
                X509Certificate nextIssuer = null;
                for (int j = 0; j < chain.Count; j++)
                {
                    if (visited.Contains(j))
                        continue;
                    X509Certificate candidate = chain[j];
                    if (candidate == null)
                        continue;
                    if (!current.IssuerDN.Equivalent(candidate.SubjectDN, true))
                        continue;
                    // Must be a CA certificate (BasicConstraints >= 0).
                    if (candidate.GetBasicConstraints() < 0)
                        continue;
                    try
                    {
                        current.Verify(candidate.GetPublicKey());
                        visited.Add(j);
                        nextIssuer = candidate;
                        break;
                    }
                    catch { }
                }

                if (nextIssuer == null)
                    break;
                current = nextIssuer;
            }

            error = "TLS certificate chain does not terminate at a trusted Root CA.";
            return false;
        }

        private static bool ByteArrayEquals(byte[] a, byte[] b)
        {
            if (a == null || b == null || a.Length != b.Length)
                return false;
            int diff = 0;
            for (int i = 0; i < a.Length; i++)
                diff |= a[i] ^ b[i];
            return diff == 0;
        }
    }
}
